		Nonce: []byte("client-nonce"),
	}

	token2 := fedAuthAckStruct{
		Nonce:     []byte("different-nonce"),
		Signature: []byte("server-signature"),
	}

	// This should fail
	if !bytes.Equal(fedAuth2.Nonce, token2.Nonce) {
		fmt.Println("ERROR: nonce mismatch between client and server")
		return
	}
	fedAuth2.Signature = token2.Signature
	fmt.Println("This should not be reached")
}
